    -- empty field) normalized to explicit-close form so the tokenizer below
    -- doesn't need a second, optional-group code path for them.
    regexp_replace(xmlrecord, '<(c\d+)([^>]*)/>', '<$1$2></$1>') AS xmlrecord_norm
