-- Three regexp_extract_all calls over one pattern give parallel arrays of
-- (tag, attributes, value); zip() stitches them back into tuples. The document
-- is scanned 3 times total, not once per output column.
-- A missing m/s attribute means 1 (T24 omits it for the first occurrence), so
-- defaulting here saves a coalesce at every downstream access.
tokens AS (
  SELECT
    recid,
    xml_hash,
    transform(
      zip(
        regexp_extract_all(xmlrecord_norm, '<(c\d+)([^>]*)>([^<]*)</c\d+>', 1),
        regexp_extract_all(xmlrecord_norm, '<(c\d+)([^>]*)>([^<]*)</c\d+>', 2),
        regexp_extract_all(xmlrecord_norm, '<(c\d+)([^>]*)>([^<]*)</c\d+>', 3)
      ),
      e -> CAST(
        ROW(
          e[1],
          CAST(COALESCE(regexp_extract(e[2], 'm="(\d+)"', 1), '1') AS INTEGER),
          CAST(COALESCE(regexp_extract(e[2], 's="(\d+)"', 1), '1') AS INTEGER),
          CASE WHEN e[3] = '' THEN NULL ELSE replace(replace(replace(replace(replace(replace(e[3], '&lt;', '<'), '&gt;', '>'), '&quot;', '"'), '&apos;', ''''), '&#39;', ''''), '&amp;', '&') END
